import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.Dp0m3YJZ.js";const k=JSON.parse('{"title":"01 · 開始使用","description":"","frontmatter":{},"headers":[],"relativePath":"topics/getting-started.md","filePath":"topics/getting-started.md","lastUpdated":null}'),n={name:"topics/getting-started.md"};function l(p,a,d,r,h,o){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="_01-·-開始使用" tabindex="-1">01 · 開始使用 <a class="header-anchor" href="#_01-·-開始使用" aria-label="Permalink to &quot;01 · 開始使用&quot;">​</a></h1><p>本章的目標是從 PowerShell 啟動 WUWAOS，分清楚主機、模擬器與客體作業系統。</p><h2 id="三個執行環境" tabindex="-1">三個執行環境 <a class="header-anchor" href="#三個執行環境" aria-label="Permalink to &quot;三個執行環境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>環境</th><th>負責什麼</th></tr></thead><tbody><tr><td>Windows／PowerShell</td><td>你輸入啟動指令的主機</td></tr><tr><td>WSL Ubuntu</td><td>用 Clang、LLD、Make 建置 RISC-V 程式，執行 QEMU</td></tr><tr><td>QEMU 裡的 WUWAOS</td><td>核心管理虛擬硬體，使用者 shell 接受 OS 指令</td></tr></tbody></table><p>QEMU 的 virt 機型提供的是指定的虛擬硬體。WUWAOS 仍須有對應驅動與核心機制才能使用裝置。</p><h2 id="建置與啟動" tabindex="-1">建置與啟動 <a class="header-anchor" href="#建置與啟動" aria-label="Permalink to &quot;建置與啟動&quot;">​</a></h2><p>WSL Ubuntu 需備有 Clang、LLD、llvm-objcopy、Make、qemu-system-riscv64 及 OpenSBI。既有 OS 驗收環境為 Clang 18、QEMU 8.2.2、OpenSBI 1.3。</p><p>在專案根目錄 <code>C:\\programing\\WUWAOS</code> 的 PowerShell 執行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d Ubuntu </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bash </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lc </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;cd /mnt/c/programing/WUWAOS &amp;&amp; make&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d Ubuntu </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bash </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lc </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;cd /mnt/c/programing/WUWAOS &amp;&amp; make run&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Makefile 先建立核心、三份使用者映像及磁碟，再啟動 QEMU。WUFS 磁碟為 <code>build/wuwaos.img</code>，交換區為 <code>build/wuwaos-swap.img</code>。<code>make clean</code> 保留磁碟；不要為重新建置而手動刪除它們，裡面可能有你的檔案。</p><h2 id="進入系統後" tabindex="-1">進入系統後 <a class="header-anchor" href="#進入系統後" aria-label="Permalink to &quot;進入系統後&quot;">​</a></h2><p>看到開機動畫和 <code>wuwaos&gt;</code> 後，以下指令才是在 WUWAOS 裡輸入：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>help</span></span>
<span class="line"><span>ps</span></span>
<span class="line"><span>vmstat</span></span>
<span class="line"><span>ls /</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>應能看到可用命令、行程資訊、分頁統計與根目錄。使用 <code>fan /home/user/note.txt</code> 可以進入編輯器；詳見<a href="./applications.html">使用者程式</a>。</p><p>按 <code>Ctrl+A</code>，放開後按 <code>X</code> 離開 QEMU。<code>exit</code> 只結束 shell，並不關閉虛擬電腦。</p><h2 id="對應程式碼" tabindex="-1">對應程式碼 <a class="header-anchor" href="#對應程式碼" aria-label="Permalink to &quot;對應程式碼&quot;">​</a></h2><p><code>Makefile</code> 負責交叉編譯、連結與 QEMU 參數；<code>tools/make_disk.py</code> 維護 WUFS 映像；<code>tools/make_swap.py</code> 建立專用交換區。它們是在主機執行的工具，不是 WUWAOS 的 syscall（系統呼叫）。</p><h2 id="閱讀與驗證邊界" tabindex="-1">閱讀與驗證邊界 <a class="header-anchor" href="#閱讀與驗證邊界" aria-label="Permalink to &quot;閱讀與驗證邊界&quot;">​</a></h2><p>本機文件網站是另一個主機程式，不在 QEMU 裡執行。其啟動方式見<a href="./writing.html">維護文件網站</a>。OS 既有操作與結果見<a href="./../history.html">規格紀錄</a>，本次文件建置不會重新驗證核心功能。</p><p>觀念參考：<code>notes/ch1 Introduction.md</code>、<code>notes/ch2 Operating-System Structures.md</code>。本章指令則依 WUWAOS 的 Makefile 與操作介面整理。</p>`,20)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
